head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getTopRowIndex]<br/>Body 영역에 렌더링 된 데이터 중 첫번째 Row 의 인덱스를 반환합니다.",
    "validation" : [
        "현재 Body 영역(뷰포트)에 실제 렌더링된 데이터 중 첫번째 Row 의 인덱스를 반환합니다. Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "visibleRowNum='all' 이면 전체 데이터가 렌더링되므로 항상 첫번째 Row 의 인덱스를 반환합니다.",
        "데이터가 렌더링 되지 않은 상태이면 -1 을 반환합니다.",
        "visibleRowNum 속성값이 'all' 이 아니면 Body 영역에 화면에 표시되는 데이터만 렌더링됩니다. 따라서 스크롤 상태에 따라 화면에 렌더링되는 데이터가 달라지며 첫번째 Row 의 인덱스도 달라집니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성 (10 행 — visibleRowNum 값에 따라 렌더 Row 수·첫번째 인덱스 차이가 보이도록 충분히 많은 데이터 확보)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // 조건 설정 (visibleRowNum 미설정 시 '' → createCList 가 빈 문자열 속성을 제외하므로 Property 미설정 상태로 생성)
    let properties = {
        visibleRowNum: con_visibleRowNum.getValue(),
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // 디자인 높이를 작게(약 3행) 설정 → 미설정('') 시 뷰포트에 맞는 Row 수만 렌더링되어 getTopRowIndex 로 확인 가능
    // 마지막 컬럼 width='*' 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:171px;">';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);

    // 렌더 의존값이므로 native setTimeout 으로 갱신 후 출력
    setTimeout(scwin.btn_getTopRowIndex_onclick, 500);
}



// getTopRowIndex 확인 — Body 뷰포트에 렌더링된 데이터 중 첫번째 Row 의 인덱스 반환 (0부터 시작)
// 초기/미설정 또는 스크롤 전 -> 0, all -> 항상 0(첫번째 Row 인덱스)
// @return : 렌더 의존값이므로 native setTimeout(500) 으로 갱신 후 읽음 ($p.setTimeout 은 stale)
scwin.btn_getTopRowIndex_onclick = function (e) {
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("getTopRowIndex() : " + target1.getTopRowIndex());
    }, 500);
}



// 아래로 스크롤 — Body 세로 스크롤을 최하단으로 이동 후 getTopRowIndex 재출력
// @spec : visibleRowNum 이 'all' 이 아니면 화면 표시 데이터만 렌더링 → 스크롤 상태에 따라 첫번째 Row 인덱스가 달라짐(증가)
scwin.btn_scrollDown_onclick = function (e) {
    let scrollArea = target1.render.querySelector('.w2grid_scrollY');
    if (scrollArea) {
        scrollArea.scrollTop = scrollArea.scrollHeight;
    }

    // 스크롤 직후 grid 내부 비동기 렌더 갱신을 기다린 뒤 읽음 (native setTimeout)
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("[스크롤 후] getTopRowIndex() : " + target1.getTopRowIndex());
    }, 500);
}



// 데이터 제거 (removeAll) — 데이터가 렌더링되지 않은 상태이면 getTopRowIndex() 는 -1 반환
scwin.btn_removeAll_onclick = function (e) {
    dlt_bind.removeAll();

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("[데이터 제거 후] getTopRowIndex() : " + target1.getTopRowIndex());
    }, 500);
}
